from itertools import permutations, product

def F(w, x, y, z):
    return ((x == (not y)) <= (not (w <= x))) or (not z)

rows = [(None, 0, 1, 0), (0, None, None, 0), (None, 1, 1, None)]
ans = set()                                  # одна расстановка подходит при разных заполнениях
for p in permutations('wxyz'):
    for fill in product([0, 1], repeat=6):      # 6 пустых клеток
        it = iter(fill)
        t = [tuple(next(it) if v is None else v for v in r) for r in rows]
        if len(set(t)) == len(t) and all(F(**dict(zip(p, r))) == 0 for r in t):
            ans.add(''.join(p))
print(*ans)

